package africa.growtogether.platform.eip.payment;
import static africa.growtogether.platform.eip.payment.PaymentDtos.*; import jakarta.validation.Valid; import java.util.UUID; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/integration/payments") public class PaymentController {private final PaymentService service; public PaymentController(PaymentService service){this.service=service;}
 @PostMapping @PreAuthorize("hasAuthority('integration.payment.create')") public PaymentView create(@Valid @RequestBody CreatePayment c){return service.create(c);} @GetMapping("/{id}") @PreAuthorize("hasAuthority('integration.payment.read')") public PaymentView get(@PathVariable UUID id){return service.get(id);}
 @PostMapping("/{id}/provider-submitted") @PreAuthorize("hasAuthority('integration.payment.execute')") public PaymentView submitted(@PathVariable UUID id,@RequestParam String providerRequestId){return service.submitted(id,providerRequestId);} @PostMapping("/{id}/succeeded") @PreAuthorize("hasAuthority('integration.payment.execute')") public PaymentView succeeded(@PathVariable UUID id,@Valid @RequestBody ProviderResult r){return service.succeed(id,r);} @PostMapping("/{id}/failed") @PreAuthorize("hasAuthority('integration.payment.execute')") public PaymentView failed(@PathVariable UUID id,@Valid @RequestBody Failure f){return service.fail(id,f);} @PostMapping("/{id}/cancel") @PreAuthorize("hasAuthority('integration.payment.manage')") public PaymentView cancel(@PathVariable UUID id){return service.cancel(id);} @PostMapping("/{id}/reverse") @PreAuthorize("hasAuthority('integration.payment.reverse')") public PaymentView reverse(@PathVariable UUID id){return service.reverse(id);}
 @PostMapping("/settlements") @PreAuthorize("hasAuthority('integration.settlement.manage')") public SettlementView settlement(@Valid @RequestBody SettlementCommand c){return service.settlement(c);} @PostMapping("/reconciliation") @PreAuthorize("hasAuthority('integration.reconciliation.manage')") public ReconciliationView reconcile(@Valid @RequestBody ReconcileCommand c){return service.reconcile(c);} @PostMapping("/disputes") @PreAuthorize("hasAuthority('integration.dispute.manage')") public UUID dispute(@Valid @RequestBody DisputeCommand c){return service.dispute(c);}
}
